"""Static response buttons: payload parsing and schema-writable memory keys.

Payloads that start with the ``set:`` prefix are set-memory candidates and must
match ``set:session.<skill_id>.<entry_name>=<value>`` (or
``set:session.project.<entry_name>=<value>`` for project memory). Split on the
first ``=`` so values may contain ``=``. Payloads without that prefix are plain
text and pass through unchanged.

:func:`is_set_memory_payload` is a prefix check only — not full grammar
validation. Malformed ``set:…`` strings fail in
:func:`parse_static_set_memory_payload`.

Write eligibility for engine ``set:`` taps (not ``set_fields``):

- The inbound payload must appear on the latest agent message's buttons
  (enforced by the inbound intercept, not this module).
- Skill-scoped ``session.<skill_id>.<entry>``: write only when *skill_id* is
  the active skill and that skill declares the field.
- Project-scoped ``session.project.<entry>``: write when the field is declared
  on project memory. The payload namespace is
  authoritative: the write targets ``project.<entry>`` even when the active skill
  declares a homonymous field. Do **not** require the field to be the active
  collect target or ``llm_settable``.
- Another skill's namespaced entries: skip.

Button-writable memory helpers live here (not on the skill catalog) so train
validation and runtime button intercepts share one schema rule set, separate
from LLM ``set_fields`` settability
(:func:`~rasa.mantle.skills.catalog.skill_settable_entry_names`).
"""

from __future__ import annotations

import json
from enum import Enum
from typing import Any, FrozenSet

from pydantic import BaseModel, ConfigDict

from rasa.mantle.memory.field import (
    MEMORY_FIELD_TYPE_BOOL,
    MEMORY_FIELD_TYPE_CATEGORICAL,
    MEMORY_FIELD_TYPE_FLOAT,
    MEMORY_FIELD_TYPE_INT,
    MEMORY_FIELD_TYPE_JSON,
    MEMORY_FIELD_TYPE_LIST,
    MemoryField,
)
from rasa.mantle.memory.manager import PROJECT_NAMESPACE
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.orchestration.correction.coercion import coerce_to_field_type
from rasa.mantle.skills.catalog import SkillCatalog

SET_MEMORY_PREFIX = "set:"
_SESSION_PREFIX = "session."

_TYPED_SCALAR_TYPES: FrozenSet[str] = frozenset(
    {
        MEMORY_FIELD_TYPE_BOOL,
        MEMORY_FIELD_TYPE_INT,
        MEMORY_FIELD_TYPE_FLOAT,
    }
)


class ParsedStaticSetMemoryPayload(BaseModel):
    """A validated static set-memory button payload."""

    model_config = ConfigDict(frozen=True)

    memory_key: str
    """Fully-qualified memory key (``{skill_id}.{entry_name}`` or
    ``project.{entry_name}``).
    """
    value: str
    """Literal value written on tap."""


class SetMemoryPayloadError(ValueError):
    """Raised when a ``set:`` payload is malformed."""


class InboundButtonPayloadKind(str, Enum):
    """How inbound user text relates to a static button payload."""

    TEXT = "text"
    SET_MEMORY = "set_memory"
    INVALID_SET_MEMORY = "invalid_set_memory"


class InboundButtonPayload(BaseModel):
    """Result of classifying inbound user text as a button payload."""

    model_config = ConfigDict(frozen=True)

    kind: InboundButtonPayloadKind
    parsed: ParsedStaticSetMemoryPayload | None = None


def is_set_memory_payload(payload: str) -> bool:
    """Return whether *payload* starts with the ``set:`` prefix.

    Prefix check only — not full grammar validation. Strings such as
    ``set: reminder`` are set-memory candidates and fail later in
    :func:`parse_static_set_memory_payload`. Case-sensitive: ``Set:`` is plain
    text.
    """
    return payload.startswith(SET_MEMORY_PREFIX)


def parse_static_set_memory_payload(payload: str) -> ParsedStaticSetMemoryPayload:
    """Parse a static ``set:`` button payload.

    Args:
        payload: Full payload string from ``responses.yml``.

    Returns:
        Parsed memory key and value.

    Raises:
        SetMemoryPayloadError: When *payload* is not plain text but does not
            match ``set:session.<skill_id>.<entry_name>=<value>`` (or
            ``set:session.project.<entry_name>=<value>``).
    """
    if not is_set_memory_payload(payload):
        raise SetMemoryPayloadError(
            f"Button payload {payload!r} is not a set-memory payload."
        )
    body = payload[len(SET_MEMORY_PREFIX) :]
    if "=" not in body:
        raise SetMemoryPayloadError(
            "Set-memory button payload must match "
            "'set:session.<skill_id|project>.<entry_name>=<value>'."
        )
    ref_part, value = body.split("=", 1)
    if not value:
        raise SetMemoryPayloadError(
            "Set-memory button payload must include a non-empty value after '='."
        )
    ref_part = ref_part.strip()
    if not ref_part.startswith(_SESSION_PREFIX):
        raise SetMemoryPayloadError(
            "Set-memory button payload memory ref must start with 'session.'."
        )
    skill_id_and_entry = ref_part[len(_SESSION_PREFIX) :]
    if skill_id_and_entry.count(".") != 1:
        raise SetMemoryPayloadError(
            "Set-memory button payload memory ref must be "
            "'session.<skill_id|project>.<entry_name>'."
        )
    skill_id, entry_name = skill_id_and_entry.split(".", 1)
    if not skill_id or not entry_name:
        raise SetMemoryPayloadError(
            "Set-memory button payload memory ref must be "
            "'session.<skill_id|project>.<entry_name>'."
        )
    return ParsedStaticSetMemoryPayload(
        memory_key=f"{skill_id}.{entry_name}",
        value=value,
    )


def classify_inbound_button_payload(payload: str) -> InboundButtonPayload:
    """Classify inbound user text as plain text, valid ``set:``, or invalid ``set:``.

    Args:
        payload: User-message text as the channel delivered it (button tap
            or typed input).

    Returns:
        Classification. ``parsed`` is set only for
        :attr:`InboundButtonPayloadKind.SET_MEMORY`.
    """
    if not is_set_memory_payload(payload):
        return InboundButtonPayload(kind=InboundButtonPayloadKind.TEXT)
    try:
        parsed = parse_static_set_memory_payload(payload)
    except SetMemoryPayloadError:
        return InboundButtonPayload(kind=InboundButtonPayloadKind.INVALID_SET_MEMORY)
    return InboundButtonPayload(
        kind=InboundButtonPayloadKind.SET_MEMORY,
        parsed=parsed,
    )


def coerce_set_memory_button_value(raw_value: str, field: MemoryField) -> Any | None:
    """Coerce a ``set:`` button payload string to *field*'s type, or ``None``.

    Button payloads are always strings after the first ``=``. Behaviour by type:

    - ``bool`` / ``int`` / ``float``: :func:`coerce_to_field_type`; reject when
      coercion leaves a string.
    - ``categorical``: reject when not in ``enum_values`` (when declared).
    - ``list``: ``json.loads`` must yield a JSON array.
    - ``json``: ``json.loads`` must succeed (any JSON value).
    - other types (``text``, ``any``, …): return the raw string.
    """
    if field.type == MEMORY_FIELD_TYPE_LIST:
        return _parse_json_list_payload(raw_value)
    if field.type == MEMORY_FIELD_TYPE_JSON:
        return _parse_json_payload(raw_value)

    coerced = coerce_to_field_type(raw_value, field)
    if field.type == MEMORY_FIELD_TYPE_CATEGORICAL and field.enum_values:
        allowed = {str(value) for value in field.enum_values}
        if str(coerced) not in allowed:
            return None
        return coerced
    if field.type in _TYPED_SCALAR_TYPES and isinstance(coerced, str):
        return None
    return coerced


def _parse_json_list_payload(raw_value: str) -> list[Any] | None:
    """Parse *raw_value* as a JSON array, or ``None`` when invalid."""
    try:
        parsed = json.loads(raw_value)
    except (TypeError, ValueError):
        return None
    if not isinstance(parsed, list):
        return None
    return parsed


def _parse_json_payload(raw_value: str) -> Any | None:
    """Parse *raw_value* as JSON, or ``None`` when invalid."""
    try:
        return json.loads(raw_value)
    except (TypeError, ValueError):
        return None


def active_skill_can_write_set_memory(
    parsed: ParsedStaticSetMemoryPayload,
    *,
    active_skill_id: str | None,
    skill_catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> bool:
    """Test whether the active skill may write *parsed* as an engine memory write.

    Does not require ``llm_settable`` or that the field is the active collect
    target. Skips another skill's namespaced entries. Uses the same declared-field
    rule as train validation.

    Args:
        parsed: Payload already parsed by :func:`parse_static_set_memory_payload`.
        active_skill_id: ``TrackerHandle.active_skill_id`` for this turn.
        skill_catalog: Loaded skill catalog (schemas).
        project_memory: Project ``memory.yml`` schema.

    Returns:
        ``True`` when the write should proceed; ``False`` to skip.
    """
    if active_skill_id is None:
        return False

    owner_id, entry_name = parsed.memory_key.split(".", 1)
    skill = skill_catalog.skill_by_id(active_skill_id)
    if skill is None:
        return False

    if owner_id == PROJECT_NAMESPACE:
        return entry_name in project_memory.fields

    if owner_id != active_skill_id:
        return False

    return entry_name in skill.memory.definition.all_fields()


def button_writable_memory_keys_for_skill(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    observing_skill_id: str | None,
) -> frozenset[str]:
    """Return fully-qualified keys a ``set:`` button may write for one skill.

    **Schema-settable for engine button taps:** every declared skill and project
    field. Does not require ``llm_settable`` or collect ownership.

    Distinct from:

    - :func:`~rasa.mantle.skills.catalog.skill_settable_entry_names` — LLM
      ``set_fields`` targets (``llm_settable`` ∪ collect-owned bare names).
    - This-turn writability — :func:`active_skill_can_write_set_memory`
      (declared own-skill and project fields against
      ``TrackerHandle.active_skill_id``).

    When *observing_skill_id* is ``None`` (no skill context), only declared
    project fields are returned.
    """
    if observing_skill_id is None:
        return frozenset(
            f"{PROJECT_NAMESPACE}.{entry_name}" for entry_name in project_memory.fields
        )

    skill = catalog.skills.get(observing_skill_id)
    if skill is None:
        return frozenset()

    keys: set[str] = set()

    for entry_name in skill.memory.definition.all_fields():
        keys.add(f"{observing_skill_id}.{entry_name}")

    for entry_name in project_memory.fields:
        keys.add(f"{PROJECT_NAMESPACE}.{entry_name}")

    return frozenset(keys)
